export function setPhaseShift(targetBoneParams, targetBone) {
    const phaseShift = targetBoneParams.PhaseShift;
    const nFrames = targetBone.nFrames;
    const shiftFrames = Math.floor(phaseShift * nFrames);

    if (shiftFrames === 0) return;

    const src = targetBone.New.QuatAnimTrack; 
    const shiftElements = shiftFrames * 4;
    const totalElements = src.length;

    const tail = src.slice(totalElements - shiftElements);

    const head = src.slice(0, totalElements - shiftElements);
    targetBone.New.QuatAnimTrack = tail.concat(head);
}
